BEGIN;
SET LOCAL search_path TO public, extensions, pg_catalog;
CREATE TABLE public."bes_extra_attendance_record_changes" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "session_id" uuid NOT NULL,
  "record_id" uuid,
  "class_id" uuid NOT NULL,
  "member_key" text DEFAULT ''::text NOT NULL,
  "student_full_name" text DEFAULT ''::text NOT NULL,
  "change_kind" text DEFAULT 'record'::text NOT NULL,
  "changed_by" uuid,
  "changed_by_name" text DEFAULT ''::text NOT NULL,
  "changed_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
  "old_status" text DEFAULT ''::text NOT NULL,
  "new_status" text DEFAULT ''::text NOT NULL,
  "old_absence_reason_code" text DEFAULT ''::text NOT NULL,
  "new_absence_reason_code" text DEFAULT ''::text NOT NULL,
  "old_absence_note" text DEFAULT ''::text NOT NULL,
  "new_absence_note" text DEFAULT ''::text NOT NULL,
  "session_note_before" text DEFAULT ''::text NOT NULL,
  "session_note_after" text DEFAULT ''::text NOT NULL
);
CREATE TABLE public."bes_extra_attendance_records" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "session_id" uuid NOT NULL,
  "class_id" uuid NOT NULL,
  "member_id" uuid,
  "member_key" text NOT NULL,
  "student_code" text DEFAULT ''::text NOT NULL,
  "student_full_name" text NOT NULL,
  "school_class_name" text DEFAULT ''::text NOT NULL,
  "status" text NOT NULL,
  "recorded_at" timestamp with time zone DEFAULT now() NOT NULL,
  "absence_reason_code" text DEFAULT ''::text NOT NULL,
  "absence_note" text DEFAULT ''::text NOT NULL
);
CREATE TABLE public."bes_extra_attendance_sessions" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "class_id" uuid NOT NULL,
  "class_type" text NOT NULL,
  "class_name" text NOT NULL,
  "subject" text DEFAULT ''::text NOT NULL,
  "teacher_id" uuid,
  "teacher_name" text DEFAULT ''::text NOT NULL,
  "teacher_email" text DEFAULT ''::text NOT NULL,
  "checked_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
  "checked_by" uuid NOT NULL,
  "total_students" integer NOT NULL,
  "present_count" integer NOT NULL,
  "absent_count" integer NOT NULL,
  "note" text DEFAULT ''::text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "attendance_date" date DEFAULT ((now() AT TIME ZONE 'Asia/Ho_Chi_Minh'::text))::date NOT NULL,
  "session_status" text DEFAULT 'completed'::text NOT NULL,
  "lesson_periods" numeric(3,1) DEFAULT 1 NOT NULL,
  "cancellation_reason" text DEFAULT ''::text NOT NULL,
  "teaching_room" text DEFAULT ''::text NOT NULL,
  "teaching_time_range" text DEFAULT ''::text NOT NULL,
  "proof_path" text,
  "checked_by_name" text DEFAULT ''::text NOT NULL
);
CREATE TABLE public."bes_extra_class_members" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "class_id" uuid NOT NULL,
  "member_key" text NOT NULL,
  "student_code" text DEFAULT ''::text NOT NULL,
  "student_full_name" text NOT NULL,
  "school_class_name" text DEFAULT ''::text NOT NULL,
  "active" boolean DEFAULT true NOT NULL,
  "joined_at" timestamp with time zone DEFAULT now() NOT NULL,
  "left_at" timestamp with time zone,
  "created_by" uuid NOT NULL,
  "updated_by" uuid NOT NULL,
  "removed_by" uuid,
  "removal_reason" text DEFAULT ''::text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "source_key" text,
  "teacher_note" text DEFAULT ''::text NOT NULL
);
CREATE TABLE public."bes_extra_class_teachers" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "class_id" uuid NOT NULL,
  "teacher_id" uuid,
  "teacher_name" text NOT NULL,
  "teacher_email" text DEFAULT ''::text NOT NULL,
  "position" integer DEFAULT 1 NOT NULL,
  "source_key" text,
  "created_by" uuid NOT NULL,
  "updated_by" uuid NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE public."bes_extra_classes" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "class_type" text NOT NULL,
  "class_name" text NOT NULL,
  "subject" text DEFAULT ''::text NOT NULL,
  "teacher_id" uuid,
  "teacher_name" text DEFAULT ''::text NOT NULL,
  "teacher_email" text DEFAULT ''::text NOT NULL,
  "active" boolean DEFAULT true NOT NULL,
  "created_by" uuid NOT NULL,
  "updated_by" uuid NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "source_key" text,
  "school_year" text DEFAULT ''::text NOT NULL,
  "grade_level" text DEFAULT ''::text NOT NULL,
  "expected_student_count" integer,
  "periods_per_week" integer,
  "room" text DEFAULT ''::text NOT NULL,
  "weekdays" text DEFAULT ''::text NOT NULL,
  "time_range" text DEFAULT ''::text NOT NULL
);
CREATE TABLE public."profiles" (
  "id" uuid NOT NULL,
  "email" text NOT NULL,
  "full_name" text,
  "school" text,
  "role" text DEFAULT 'teacher'::text NOT NULL,
  "approved" boolean DEFAULT false NOT NULL,
  "permissions" jsonb DEFAULT '{"mode": "all", "allowed": []}'::jsonb NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "username" text,
  "contact_email" text,
  "auth_mode" text DEFAULT 'email'::text NOT NULL,
  "must_change_password" boolean DEFAULT false NOT NULL,
  "job_title" text,
  "phone" text,
  "bio" text,
  "avatar_url" text
);
CREATE TABLE public."system_roles" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" uuid NOT NULL,
  "role" text NOT NULL,
  "scope" text DEFAULT 'system'::text NOT NULL,
  "active" boolean DEFAULT true NOT NULL,
  "assigned_by" uuid,
  "assigned_at" timestamp with time zone DEFAULT now() NOT NULL,
  "metadata" jsonb DEFAULT '{}'::jsonb NOT NULL
);
ALTER TABLE public."bes_extra_attendance_record_changes" ADD CONSTRAINT "bes_extra_attendance_record_changes_change_kind_check" CHECK (change_kind = ANY (ARRAY['record'::text, 'session_note'::text]));
ALTER TABLE public."bes_extra_attendance_record_changes" ADD CONSTRAINT "bes_extra_attendance_record_changes_pkey" PRIMARY KEY (id);
ALTER TABLE public."bes_extra_attendance_records" ADD CONSTRAINT "bes_extra_attendance_records_absence_reason_check" CHECK ((status = ANY (ARRAY['present'::text, 'late'::text])) AND absence_reason_code = ''::text AND absence_note = ''::text OR status = 'absent'::text AND (absence_reason_code = ANY (ARRAY['excused'::text, 'unexcused'::text, 'sick'::text, 'family'::text, 'other'::text, 'unspecified'::text])) AND (absence_reason_code <> 'other'::text OR length(TRIM(BOTH FROM absence_note)) > 0));
ALTER TABLE public."bes_extra_attendance_records" ADD CONSTRAINT "bes_extra_attendance_records_pkey" PRIMARY KEY (id);
ALTER TABLE public."bes_extra_attendance_records" ADD CONSTRAINT "bes_extra_attendance_records_session_id_member_key_key" UNIQUE (session_id, member_key);
ALTER TABLE public."bes_extra_attendance_records" ADD CONSTRAINT "bes_extra_attendance_records_status_check" CHECK (status = ANY (ARRAY['present'::text, 'late'::text, 'absent'::text]));
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_session_count_check" CHECK ((present_count + absent_count) = total_students);
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_absent_count_check" CHECK (absent_count >= 0);
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_cancel_reason_check" CHECK (session_status = 'completed'::text AND cancellation_reason = ''::text OR session_status = 'cancelled'::text AND length(TRIM(BOTH FROM cancellation_reason)) > 0);
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_class_type_check" CHECK (class_type = ANY (ARRAY['remedial'::text, 'gifted'::text]));
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_periods_check" CHECK (session_status = 'completed'::text AND (lesson_periods = ANY (ARRAY[1::numeric, 1.5, 2::numeric])) OR session_status = 'cancelled'::text AND lesson_periods = 0::numeric);
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_pkey" PRIMARY KEY (id);
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_present_count_check" CHECK (present_count >= 0);
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_status_check" CHECK (session_status = ANY (ARRAY['completed'::text, 'cancelled'::text]));
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_total_students_check" CHECK (total_students >= 0);
ALTER TABLE public."bes_extra_class_members" ADD CONSTRAINT "bes_extra_class_members_pkey" PRIMARY KEY (id);
ALTER TABLE public."bes_extra_class_teachers" ADD CONSTRAINT "bes_extra_class_teachers_pkey" PRIMARY KEY (id);
ALTER TABLE public."bes_extra_class_teachers" ADD CONSTRAINT "bes_extra_class_teachers_position_check" CHECK ("position" > 0);
ALTER TABLE public."bes_extra_classes" ADD CONSTRAINT "bes_extra_classes_class_type_check" CHECK (class_type = ANY (ARRAY['remedial'::text, 'gifted'::text]));
ALTER TABLE public."bes_extra_classes" ADD CONSTRAINT "bes_extra_classes_pkey" PRIMARY KEY (id);
ALTER TABLE public."profiles" ADD CONSTRAINT "profiles_email_key" UNIQUE (email);
ALTER TABLE public."profiles" ADD CONSTRAINT "profiles_pkey" PRIMARY KEY (id);
ALTER TABLE public."profiles" ADD CONSTRAINT "profiles_role_check" CHECK (lower(COALESCE(role, 'teacher'::text)) = ANY (ARRAY['teacher'::text, 'admin'::text, 'department_head'::text, 'department-head'::text, 'ttcm'::text, 'to_truong'::text, 'tổ trưởng'::text, 'department_leader'::text, 'department leader'::text, 'subject_leader'::text, 'subject leader'::text, 'leader'::text]));
ALTER TABLE public."system_roles" ADD CONSTRAINT "system_roles_pkey" PRIMARY KEY (id);
ALTER TABLE public."system_roles" ADD CONSTRAINT "system_roles_role_check" CHECK (role = ANY (ARRAY['admin'::text, 'department_head'::text, 'teacher'::text, 'student'::text]));
ALTER TABLE public."system_roles" ADD CONSTRAINT "system_roles_user_id_scope_key" UNIQUE (user_id, scope);
ALTER TABLE public."bes_extra_attendance_record_changes" ADD CONSTRAINT "bes_extra_attendance_record_changes_changed_by_fkey" FOREIGN KEY (changed_by) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE public."bes_extra_attendance_record_changes" ADD CONSTRAINT "bes_extra_attendance_record_changes_class_id_fkey" FOREIGN KEY (class_id) REFERENCES bes_extra_classes(id) ON DELETE CASCADE;
ALTER TABLE public."bes_extra_attendance_record_changes" ADD CONSTRAINT "bes_extra_attendance_record_changes_record_id_fkey" FOREIGN KEY (record_id) REFERENCES bes_extra_attendance_records(id) ON DELETE CASCADE;
ALTER TABLE public."bes_extra_attendance_record_changes" ADD CONSTRAINT "bes_extra_attendance_record_changes_session_id_fkey" FOREIGN KEY (session_id) REFERENCES bes_extra_attendance_sessions(id) ON DELETE CASCADE;
ALTER TABLE public."bes_extra_attendance_records" ADD CONSTRAINT "bes_extra_attendance_records_class_id_fkey" FOREIGN KEY (class_id) REFERENCES bes_extra_classes(id) ON DELETE RESTRICT;
ALTER TABLE public."bes_extra_attendance_records" ADD CONSTRAINT "bes_extra_attendance_records_member_id_fkey" FOREIGN KEY (member_id) REFERENCES bes_extra_class_members(id) ON DELETE SET NULL;
ALTER TABLE public."bes_extra_attendance_records" ADD CONSTRAINT "bes_extra_attendance_records_session_id_fkey" FOREIGN KEY (session_id) REFERENCES bes_extra_attendance_sessions(id) ON DELETE CASCADE;
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_checked_by_fkey" FOREIGN KEY (checked_by) REFERENCES profiles(id) ON DELETE RESTRICT;
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_class_id_fkey" FOREIGN KEY (class_id) REFERENCES bes_extra_classes(id) ON DELETE RESTRICT;
ALTER TABLE public."bes_extra_attendance_sessions" ADD CONSTRAINT "bes_extra_attendance_sessions_teacher_id_fkey" FOREIGN KEY (teacher_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE public."bes_extra_class_members" ADD CONSTRAINT "bes_extra_class_members_class_id_fkey" FOREIGN KEY (class_id) REFERENCES bes_extra_classes(id) ON DELETE RESTRICT;
ALTER TABLE public."bes_extra_class_members" ADD CONSTRAINT "bes_extra_class_members_created_by_fkey" FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE RESTRICT;
ALTER TABLE public."bes_extra_class_members" ADD CONSTRAINT "bes_extra_class_members_removed_by_fkey" FOREIGN KEY (removed_by) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE public."bes_extra_class_members" ADD CONSTRAINT "bes_extra_class_members_updated_by_fkey" FOREIGN KEY (updated_by) REFERENCES profiles(id) ON DELETE RESTRICT;
ALTER TABLE public."bes_extra_class_teachers" ADD CONSTRAINT "bes_extra_class_teachers_class_id_fkey" FOREIGN KEY (class_id) REFERENCES bes_extra_classes(id) ON DELETE CASCADE;
ALTER TABLE public."bes_extra_class_teachers" ADD CONSTRAINT "bes_extra_class_teachers_created_by_fkey" FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE RESTRICT;
ALTER TABLE public."bes_extra_class_teachers" ADD CONSTRAINT "bes_extra_class_teachers_teacher_id_fkey" FOREIGN KEY (teacher_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE public."bes_extra_class_teachers" ADD CONSTRAINT "bes_extra_class_teachers_updated_by_fkey" FOREIGN KEY (updated_by) REFERENCES profiles(id) ON DELETE RESTRICT;
ALTER TABLE public."bes_extra_classes" ADD CONSTRAINT "bes_extra_classes_created_by_fkey" FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE RESTRICT;
ALTER TABLE public."bes_extra_classes" ADD CONSTRAINT "bes_extra_classes_teacher_id_fkey" FOREIGN KEY (teacher_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE public."bes_extra_classes" ADD CONSTRAINT "bes_extra_classes_updated_by_fkey" FOREIGN KEY (updated_by) REFERENCES profiles(id) ON DELETE RESTRICT;
ALTER TABLE public."profiles" ADD CONSTRAINT "profiles_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;
CREATE INDEX bes_extra_attendance_record_changes_record_idx ON public.bes_extra_attendance_record_changes USING btree (record_id, changed_at DESC) WHERE (record_id IS NOT NULL);
CREATE INDEX bes_extra_attendance_record_changes_session_idx ON public.bes_extra_attendance_record_changes USING btree (session_id, changed_at DESC);
CREATE INDEX fk_bes_extra_attendance_record_changes_c3f4d0a3 ON public.bes_extra_attendance_record_changes USING btree (record_id);
CREATE INDEX fk_bes_extra_attendance_record_changes_605dbcbf ON public.bes_extra_attendance_record_changes USING btree (class_id);
CREATE INDEX fk_bes_extra_attendance_record_changes_1a652d91 ON public.bes_extra_attendance_record_changes USING btree (changed_by);
ALTER TABLE public."bes_extra_attendance_record_changes" ENABLE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE public."bes_extra_attendance_record_changes" FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL PRIVILEGES ON SEQUENCE public.bes_extra_attendance_record_changes_id_seq FROM PUBLIC, anon, authenticated, service_role;
CREATE INDEX fk_bes_extra_attendance_records_7f5a0d1b ON public.bes_extra_attendance_records USING btree (class_id);
CREATE INDEX fk_bes_extra_attendance_records_4f2ee9f0 ON public.bes_extra_attendance_records USING btree (member_id);
CREATE INDEX bes_extra_attendance_records_session_idx ON public.bes_extra_attendance_records USING btree (session_id, status, student_full_name);
ALTER TABLE public."bes_extra_attendance_records" ENABLE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE public."bes_extra_attendance_records" FROM PUBLIC, anon, authenticated, service_role;
CREATE UNIQUE INDEX bes_extra_attendance_sessions_teacher_day_uidx ON public.bes_extra_attendance_sessions USING btree (attendance_date, lower(TRIM(BOTH FROM teacher_name))) WHERE ((session_status = 'completed'::text) AND (length(TRIM(BOTH FROM teacher_name)) > 0));
CREATE INDEX bes_extra_attendance_sessions_checked_idx ON public.bes_extra_attendance_sessions USING btree (checked_at DESC, class_id);
CREATE INDEX fk_bes_extra_attendance_sessions_62e45ba5 ON public.bes_extra_attendance_sessions USING btree (teacher_id);
CREATE INDEX fk_bes_extra_attendance_sessions_a6209134 ON public.bes_extra_attendance_sessions USING btree (checked_by);
CREATE UNIQUE INDEX bes_extra_attendance_sessions_class_date_uidx ON public.bes_extra_attendance_sessions USING btree (class_id, attendance_date);
CREATE INDEX bes_extra_attendance_sessions_class_month_idx ON public.bes_extra_attendance_sessions USING btree (class_id, attendance_date, checked_at DESC);
ALTER TABLE public."bes_extra_attendance_sessions" ENABLE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE public."bes_extra_attendance_sessions" FROM PUBLIC, anon, authenticated, service_role;
CREATE UNIQUE INDEX bes_extra_class_members_source_key_uidx ON public.bes_extra_class_members USING btree (source_key);
CREATE INDEX fk_bes_extra_class_members_6bfe53f5 ON public.bes_extra_class_members USING btree (updated_by);
CREATE UNIQUE INDEX bes_extra_class_members_active_uidx ON public.bes_extra_class_members USING btree (class_id, member_key) WHERE (active = true);
CREATE INDEX fk_bes_extra_class_members_2a8760cf ON public.bes_extra_class_members USING btree (created_by);
CREATE INDEX fk_bes_extra_class_members_405b0f86 ON public.bes_extra_class_members USING btree (removed_by);
CREATE INDEX bes_extra_class_members_class_idx ON public.bes_extra_class_members USING btree (class_id, active, student_full_name);
ALTER TABLE public."bes_extra_class_members" ENABLE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE public."bes_extra_class_members" FROM PUBLIC, anon, authenticated, service_role;
CREATE UNIQUE INDEX bes_extra_class_teachers_source_key_uidx ON public.bes_extra_class_teachers USING btree (source_key);
CREATE INDEX fk_bes_extra_class_teachers_f0fb4770 ON public.bes_extra_class_teachers USING btree (teacher_id);
CREATE INDEX fk_bes_extra_class_teachers_999f8dcc ON public.bes_extra_class_teachers USING btree (updated_by);
CREATE INDEX bes_extra_class_teachers_class_idx ON public.bes_extra_class_teachers USING btree (class_id, "position", teacher_name);
CREATE INDEX fk_bes_extra_class_teachers_7461482d ON public.bes_extra_class_teachers USING btree (created_by);
CREATE UNIQUE INDEX bes_extra_class_teachers_class_name_uidx ON public.bes_extra_class_teachers USING btree (class_id, lower(TRIM(BOTH FROM teacher_name)));
ALTER TABLE public."bes_extra_class_teachers" ENABLE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE public."bes_extra_class_teachers" FROM PUBLIC, anon, authenticated, service_role;
CREATE INDEX fk_bes_extra_classes_01f81db3 ON public.bes_extra_classes USING btree (created_by);
CREATE INDEX fk_bes_extra_classes_f47670e4 ON public.bes_extra_classes USING btree (updated_by);
CREATE UNIQUE INDEX bes_extra_classes_source_key_uidx ON public.bes_extra_classes USING btree (source_key);
CREATE UNIQUE INDEX bes_extra_classes_active_identity_uidx ON public.bes_extra_classes USING btree (class_type, lower(class_name), lower(subject), COALESCE(teacher_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(teacher_email)) WHERE (active = true);
CREATE INDEX bes_extra_classes_teacher_idx ON public.bes_extra_classes USING btree (teacher_id, active, class_type);
ALTER TABLE public."bes_extra_classes" ENABLE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE public."bes_extra_classes" FROM PUBLIC, anon, authenticated, service_role;
CREATE UNIQUE INDEX profiles_username_lower_unique ON public.profiles USING btree (lower(username)) WHERE ((username IS NOT NULL) AND (btrim(username) <> ''::text));
CREATE UNIQUE INDEX profiles_contact_email_lower_unique ON public.profiles USING btree (lower(contact_email)) WHERE ((contact_email IS NOT NULL) AND (btrim(contact_email) <> ''::text));
CREATE INDEX profiles_auth_mode_idx ON public.profiles USING btree (auth_mode);
ALTER TABLE public."profiles" ENABLE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE public."profiles" FROM PUBLIC, anon, authenticated, service_role;
CREATE INDEX system_roles_user_active_idx ON public.system_roles USING btree (user_id, active);
ALTER TABLE public."system_roles" ENABLE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE public."system_roles" FROM PUBLIC, anon, authenticated, service_role;
COMMIT;
